// ─────────────────────────────────────────────────────────────────────────────
// Normalize Instagram Payload
// Handles both direct messages (messaging[]) and comment changes (changes[]).
// IMPORTANT: Echo detection is preserved here and propagated so that the
// downstream 'Is Message Echo' guard node can route correctly, mirroring
// the Facebook-Integration pattern.
// ─────────────────────────────────────────────────────────────────────────────

const meta = $json.body || $json;
const entry = meta && meta.entry && meta.entry[0];
if (!entry) return [];

const messaging = entry.messaging && entry.messaging[0];
const changeValue = entry.changes && entry.changes[0] && entry.changes[0].value;

// ── Resolve Instagram Account ID ─────────────────────────────────────────────
const instagramAccountId =
  entry.id ||
  (messaging && messaging.recipient && messaging.recipient.id) ||
  (changeValue && changeValue.recipient && changeValue.recipient.id) ||
  '';

// ── Direct Message (Messenger / IG DM) ───────────────────────────────────────
if (messaging) {
  // Card button tap. Instagram delivers it as a postback with the payload
  // ORDER:<productId>; the AI gets a marker, the inbox keeps the title.
  const postback = messaging.postback;
  if (postback && typeof postback.payload === 'string' && postback.payload.indexOf('ORDER:') === 0) {
    const psid = messaging.sender && messaging.sender.id;
    if (!psid || !instagramAccountId) return [];
    return [{
      json: {
        instagramAccountId,
        senderId: psid,
        sessionId: 'ig_' + psid,
        isEcho: false,
        userMessage: '[ORDER_CARD:' + postback.payload.slice(6) + '] ' + (postback.title || ''),
        mediaType: 'text',
        mediaUrl: ''
      }
    }];
  }

  // Any other button tap still reaches the AI instead of being silently dropped.
  if (postback) {
    const psid = messaging.sender && messaging.sender.id;
    if (!psid || !instagramAccountId) return [];
    return [{
      json: {
        instagramAccountId,
        senderId: psid,
        sessionId: 'ig_' + psid,
        isEcho: false,
        userMessage: postback.title || String(postback.payload || ''),
        mediaType: 'text',
        mediaUrl: ''
      }
    }];
  }

  const msg = messaging.message || {};
  const replyToMessageId = (msg.reply_to && msg.reply_to.mid) || '';

  // Detect echo: messages sent by the merchant via Meta Business Suite
  const isEcho = Boolean(msg.is_echo);

  // Echo ID swap: sender/recipient are swapped for echo messages
  // - Echo: sender = IGSID of page/account, recipient = customer IGSID
  // - Normal: sender = customer IGSID, recipient = IGSID of page/account
  const senderId = isEcho
    ? (messaging.recipient && messaging.recipient.id)
    : (messaging.sender && messaging.sender.id);

  if (!senderId || !instagramAccountId) return [];

  // Skip deleted messages
  if (msg.is_deleted) return [];

  let userMessage = msg.text || '';
  let mediaType = 'text';
  let mediaUrl = '';
  const att = msg.attachments && msg.attachments[0];
  if (att && att.type === 'image') {
    mediaType = 'image';
    mediaUrl = (att.payload && att.payload.url) || '';
  } else if (att && att.type === 'audio') {
    mediaType = 'audio';
    mediaUrl = (att.payload && att.payload.url) || '';
  } else if (att) {
    // A video, sticker or file is a real message this channel cannot read.
    // Saying so keeps the conversation alive; returning nothing — what an empty
    // text used to do — dropped it silently and looked like the bot was broken.
    userMessage = userMessage ? userMessage + '\n' + '[The customer sent an attachment this channel cannot process (for example a video, a sticker or a file). Politely ask them to describe it in text, or send a photo or a voice note instead.]' : '[The customer sent an attachment this channel cannot process (for example a video, a sticker or a file). Politely ask them to describe it in text, or send a photo or a voice note instead.]';
  }

  // For non-echo messages, require actual content
  if (!isEcho && !userMessage && mediaType === 'text') return [];

  const sessionId = 'ig_' + senderId;

  return [{
    json: {
      instagramAccountId,
      senderId,
      sessionId,
      isEcho,
      messageId: msg.mid || '',
      replyToMessageId,
      userMessage,
      mediaType,
      mediaUrl
    }
  }];
}

// ── Comment / Story Reply via Changes ─────────────────────────────────────────
if (changeValue) {
  const senderId =
    (changeValue.sender && changeValue.sender.id) ||
    (changeValue.from && changeValue.from.id) ||
    '';
  if (!senderId || senderId === instagramAccountId) return [];

  const userMessage =
    (changeValue.message && changeValue.message.text) ||
    changeValue.text ||
    '';
  if (!userMessage) return [];

  return [{
    json: {
      instagramAccountId,
      senderId,
      sessionId: 'ig_' + senderId,
      isEcho: false,
      userMessage,
      mediaType: 'text',
      mediaUrl: ''
    }
  }];
}

return [];

// ─────────────────────────────────────────────────────────────────────────────
// Build Brain Payload (Instagram)
// Assembles the normalized context object for Core AI Brain.
// Mirror of the Facebook-Integration Build Brain Payload pattern.
// ─────────────────────────────────────────────────────────────────────────────

const igPayload   = $('Normalize Instagram Payload').item.json;
const integration = $('Fetch Integration Secrets').item.json;

const chatbotId   = integration.chatbotId;
const sessionId   = igPayload.sessionId;
const senderId    = igPayload.senderId || '';
const userMessage = igPayload.userMessage;
const mediaType   = igPayload.mediaType;
const mediaUrl    = igPayload.mediaUrl;

// Upsert payload passed to the Upsert Chat Session PostgreSQL node
const upsertPayload = {
  chatbotId,
  sessionId,
  guestName: 'Instagram User',
  profilePhoto: ''
};

return [{
  json: {
    chatbotId,
    sessionId,
    customerName: 'Instagram User',
    profilePhoto: null,
    userMessage,
    messageId: igPayload.messageId || '',
    replyToMessageId: igPayload.replyToMessageId || '',
    mediaType,
    mediaUrl,
    // Meta serves Facebook/Instagram media from public URLs, so no header is needed.
    mediaAuthHeader: '',
    platform: 'instagram',
    _upsert: upsertPayload
  }
}];

// Instagram generic-template carousel: same limits as Messenger (10 cards,
// up to two buttons, 80-character title/subtitle). Instagram has no typing
// indicator, but carousels work on the mobile app. A product with a public
// post URL gets a second button that opens the original post with every photo.
const cards = $('Execute Core AI Brain').item.json.productCards || [];

const elements = cards.slice(0, 10).map((card) => {
  const currency = String(card.currency || 'BDT');
  const amount = Number(card.price);
  const price = Number.isFinite(amount)
    ? (currency === 'BDT' ? '৳' : currency + ' ') + amount.toLocaleString('en-US')
    : String(card.price || '');

  // The second button is the original post, where every photo of the product
  // lives. web_url needs an absolute HTTPS URL, so a missing or relative
  // postUrl drops only the button - never the whole card.
  const postUrl = String(card.postUrl || '');
  const buttons = [
    {
      type: 'postback',
      title: '🛒 Order',
      payload: 'ORDER:' + card.productId
    }
  ];
  if (/^https:\/\//i.test(postUrl)) {
    buttons.push({ type: 'web_url', title: '🖼️ Details', url: postUrl });
  }

  return {
    title: String(card.name || '').slice(0, 80),
    subtitle: price.slice(0, 80),
    image_url: String(card.imageUrl || ''),
    buttons
  };
}).filter((element) => /^https:\/\//i.test(element.image_url));

return [{
  json: {
    carouselBody: {
      attachment: {
        type: 'template',
        payload: {
          template_type: 'generic',
          elements
        }
      }
    }
  }
}];
